#include <stdio.h>

int main(void) {
    FILE *out = fopen("flight.log", "w");
    if (out == NULL) {
        perror("flight.log");
        return 1;
    }
    fprintf(out, "altitude %d\n", 1200);
    fprintf(out, "speed %d\n", 340);
    fclose(out);

    FILE *in = fopen("flight.log", "r");
    if (in == NULL) {
        perror("flight.log");
        return 1;
    }
    char line[64];
    int n = 0;
    while (fgets(line, sizeof line, in) != NULL) {
        n++;
        printf("%d: %s", n, line);
    }
    fclose(in);
    return 0;
}

