#include <stdio.h>
#include <errno.h>
#include <string.h>

FILE *open_log(const char *name) {
    FILE *f = fopen(name, "r");
    if (f == NULL) printf("can't open %s: %s\n", name, strerror(errno));
    return f;
}

int main(void) {
    FILE *backup = fopen("backup.log", "w");
    if (backup == NULL) return 1;
    fprintf(backup, "all systems nominal\n");
    fclose(backup);

    FILE *f = open_log("main.log");
    if (f == NULL) f = open_log("backup.log");
    if (f == NULL) return 1;

    char line[64];
    if (fgets(line, sizeof line, f) != NULL) printf("read: %s", line);
    fclose(f);
    return 0;
}

