#include <stdio.h>

int main(void) {
    FILE *f = fopen("crew.txt", "w");
    if (f == NULL) return 1;
    fprintf(f, "Asha 31\nRavi 27\n???\nMeera 45\n");
    fclose(f);

    f = fopen("crew.txt", "r");
    if (f == NULL) return 1;
    char line[80], name[32];
    int age, total = 0, count = 0;
    while (fgets(line, sizeof line, f) != NULL) {
        if (sscanf(line, "%31s %d", name, &age) != 2) {
            printf("skipped: %s", line);
            continue;
        }
        total += age;
        count++;
    }
    fclose(f);
    printf("%d crew, average age %d\n", count, total / count);
    return 0;
}

